import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Tech Talk: A Different Scale, Running Small Ceph Clusters in Multiple Data Centers 20200723","description":"","frontmatter":{"title":"Ceph Tech Talk: A Different Scale, Running Small Ceph Clusters in Multiple Data Centers 20200723","date":"2020-07-28T00:00:00.000Z","updated":"2020-07-29T00:00:00.000Z","tags":["Ceph","分布式存储","小型集群","多数据中心","存储优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Tech_Talk_-_A_Different_Scale_Running_Small_Ceph_Clusters_in_Multiple_Data_Centers_20200723.md","filePath":"posts/2020/Ceph_Tech_Talk_-_A_Different_Scale_Running_Small_Ceph_Clusters_in_Multiple_Data_Centers_20200723.md","lastUpdated":1780459816000}'),n={name:"posts/2020/Ceph_Tech_Talk_-_A_Different_Scale_Running_Small_Ceph_Clusters_in_Multiple_Data_Centers_20200723.md"};function r(_,l,s,o,u,h){return a(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>讨论在不同数据中心运行小型Ceph子集群的实践和优势</p><h4 id="主讲人" tabindex="-1">主讲人： <a class="header-anchor" href="#主讲人" aria-label="Permalink to &quot;主讲人：&quot;">​</a></h4><p>Yuval（系统工程师，拥有17年系统工作经验，目前在柏林工作，自2017年起开始使用Ceph）</p><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>个人背景介绍</strong>：</p><ul><li>Yuval拥有丰富的系统工作经验，专注于多种存储系统。</li><li>目前在柏林工作，担任系统工程师。</li><li>自2017年起使用Ceph，首次接触版本为Jewel。</li></ul></li><li><p><strong>讨论小型子集群的原因</strong>：</p><ul><li>小型集群不仅实用，还具备潜在优势。</li><li>小型集群易于扩展和管理，可根据需求增加磁盘或节点。</li></ul></li><li><p><strong>使用案例介绍</strong>：</p><ul><li>在不同地点运行多个小型子集群。</li><li>计划升级到Octopus版本。</li><li>集群配置为四节点，三路复制，每个集群有三台监控器和三台管理器。</li><li>使用Ceph作为后端存储，直接连接到虚拟磁盘。</li></ul></li><li><p><strong>关于小型集群的常见问题</strong>：</p><ul><li>是否需要四节点？是否浪费资源？</li><li>小型集群的优势包括避免脑裂问题、可调整的复制级别、易于扩展和维护。</li></ul></li><li><p><strong>小型集群与大型集群的比较</strong>：</p><ul><li>小型集群更易于手动管理，自动化需求较低。</li><li>手动升级和维护时间较短，例如从Mimic升级到Nautilus仅需40分钟。</li></ul></li><li><p><strong>生产环境中的真实故事</strong>：</p><ul><li>HDD到SSD的迁移策略。</li><li>节点更换和命名一致性的重要性。</li><li>减少PG数量以适应新的OSD配置。</li><li>集群间服务迁移的策略，使用Zstandard压缩算法进行数据迁移。</li></ul></li><li><p><strong>问答环节</strong>：</p><ul><li>讨论了PG数量和内存使用的问题。</li><li>分享了关于PG比例和内存使用的实际经验。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>小型集群在多数据中心中的应用具有实际优势，特别是在避免脑裂问题、易于管理和扩展方面。</li><li>小型集群的维护和升级相对简单，适合手动管理。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控和优化小型集群的性能和资源使用。</li><li>考虑在未来的升级中采用更高效的数据迁移策略。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>感谢参与者的提问和分享，鼓励进一步的技术交流和合作。</li></ul>',13)])])}const d=e(n,[["render",r]]);export{c as __pageData,d as default};
